pub(crate) fn check_limit_opt<T: PartialOrd>(
    value_fn: impl FnOnce() -> Option<T>,
    limit: Option<T>,
) -> bool {
    let Some(limit) = limit else {
        return true; // ❌ No limit configured → passes through
    };
    let Some(value) = value_fn() else {
        return true;
    };
    value <= limit // ❌ Only checks if value <= configured max, NOT absolute max=1000
}

